BEGIN;
CREATE TABLE bni_pay_merchant (merchant_id text PRIMARY KEY, display_name text NOT NULL, settlement_account_reference text NOT NULL REFERENCES ledger_account(account_reference), status text NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED')), created_at timestamptz NOT NULL);
CREATE TABLE bni_pay_terminal (terminal_id text PRIMARY KEY, merchant_id text NOT NULL REFERENCES bni_pay_merchant(merchant_id), device_reference text NOT NULL UNIQUE, public_key_spki bytea NOT NULL, status text NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED','REVOKED')), created_at timestamptz NOT NULL);
CREATE TABLE bni_pay_intent (payment_intent_id text PRIMARY KEY, transaction_reference text NOT NULL UNIQUE, merchant_id text NOT NULL REFERENCES bni_pay_merchant(merchant_id), terminal_id text NOT NULL REFERENCES bni_pay_terminal(terminal_id), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL, terminal_nonce_hash text NOT NULL, status text NOT NULL CHECK (status IN ('PENDING','APPROVED','DECLINED','CANCELLED','EXPIRED','REFUNDED')), signature bytea NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, approved_at timestamptz, decision_reason text);
CREATE TABLE bni_pay_payment (payment_intent_id text PRIMARY KEY REFERENCES bni_pay_intent(payment_intent_id), customer_reference text NOT NULL, customer_account_reference text NOT NULL REFERENCES ledger_account(account_reference), transaction_reference text NOT NULL UNIQUE REFERENCES ledger_journal(journal_reference), status text NOT NULL, correlation_id text NOT NULL, decided_at timestamptz NOT NULL);
CREATE TABLE bni_pay_refund (refund_reference text PRIMARY KEY, original_payment_intent_id text NOT NULL REFERENCES bni_pay_payment(payment_intent_id), original_transaction_reference text NOT NULL, transaction_reference text NOT NULL UNIQUE REFERENCES ledger_journal(journal_reference), status text NOT NULL, created_at timestamptz NOT NULL, idempotency_key text NOT NULL UNIQUE);
CREATE UNIQUE INDEX uq_bni_pay_terminal_nonce ON bni_pay_intent(terminal_id, terminal_nonce_hash);
CREATE INDEX idx_bni_pay_merchant_history ON bni_pay_intent(merchant_id, created_at DESC);
INSERT INTO platform_schema_version(version) VALUES (4);
COMMIT;
